n = int(input())
a = list(map(int, input().split()))
s = input()
maxSuff = 0
cnt = 0
for i in range(n):
	if s[i] == 'A':
		maxSuff += a[i]
	else:
		cnt += a[i]
suff = []
suff.append(maxSuff)
for i in range(1, n):
	if s[i - 1] == 'A':
		suff.append(suff[i - 1] - a[i - 1])
	else:
		suff.append(suff[i - 1] + a[i - 1])
maxPref = 0
s = s[::-1]
a = a[::-1]
for i in range(n):
	if s[i] == 'A':
		maxPref += a[i]
pref = []
pref.append(maxPref)
for i in range(1, n):
	if s[i - 1] == 'A':
		pref.append(pref[i - 1] - a[i - 1])
	else:
		pref.append(pref[i - 1] + a[i - 1])
print(max(max(max(pref), max(suff)), cnt))
